import React from 'react';
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';

// Importante: Corrigir ícones do Leaflet que as vezes quebram no build do React
import L from 'leaflet';
import markerIcon from 'leaflet/dist/images/marker-icon.png';
import markerShadow from 'leaflet/dist/images/marker-shadow.png';

let DefaultIcon = L.icon({
    iconUrl: markerIcon,
    shadowUrl: markerShadow,
    iconSize: [25, 41],
    iconAnchor: [12, 41]
});
L.Marker.prototype.options.icon = DefaultIcon;

    // const map = L.map(mapRef.current).setView([-23.55, -46.63], 13)

    // L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
    //   attribution: '&copy; OpenStreetMap contributors'
    // }).addTo(map)

    // L.marker([-23.4747024, -46.7547824]).addTo(map)
    //   .bindPopup('São Paulo 🚀')
    //   .openPopup()


const Map = () => {
  const position = [-23.55, -46.63]; // Brasília

  return (
    <div style={{ height: "100vh", width: "100vw" }}>

      <MapContainer 
        center={position} 
        zoom={4} 
        style={{ height: "100%", width: "100%", zIndex:"0"}}
      >
        {/* Usando a mesma lógica de TileLayer para o Google Maps */}
        <TileLayer
          url="https://{s}.google.com/vt/lyrs=m&x={x}&y={y}&z={z}"
          subdomains={['mt0', 'mt1', 'mt2', 'mt3']}
          attribution='&copy; Google Maps'
        />
        
        <Marker position={position}>
          <Popup>
            Olá! Isso é um mapa do Google dentro do React.
          </Popup>
        </Marker>
      </MapContainer>
    </div>
  );
};

export default Map;
